const e=JSON.parse(`[{"id":"upsc-2017-prelims-csat-a-001","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":1,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What does the above passage imply?","options":{"a":"Resource-based conflicts are always politically motivated.","b":"There are no political solutions to resolve environmental and resource based conflicts.","c":"Environmental issues contribute to resource stresses and political conflict.","d":"Political conflict based on identity or ideology cannot be resolved."},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":3,"blocks":[{"type":"passage","text":"What climate change will undeniably do is cause or amplify events that hasten the reduction of resources. Competition over these diminishing resources would ensue in the form of political or even violent conflict. Resource based conflicts have rarely been overt and are thus difficult to isolate. Instead they take on veneers that appear more politically palatable. Conflicts over resources like water are often cloaked in the guise of identity or ideology."},{"type":"paragraph","text":"What does the above passage imply?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The passage links environmental scarcity to competition and political conflict; identity or ideology can conceal an underlying resource dispute.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-002","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":2,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The keynote that seems to be emerging from the passage is that","options":{"a":"we should first consult wisely and then resolve firmly","b":"we should reject suggestions of friends and remain unchanged","c":"we should always remain broad-minded","d":"we should be resolute and achievement-oriented"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":3,"blocks":[{"type":"passage","text":"The man who is perpetually hesitating which of the two things he will do first, will do neither. The man who resolves, but suffers his resolution to be changed by the first counter-suggestion of a friend—who fluctuates from opinion to opinion and veers from plan to plan—can never accomplish anything. He will at best be stationary and probably retrograde in all. It is only the man who first consults wisely, then resolves firmly and then executes his purpose with inflexible perseverance, undismayed by those petty difficulties which daunt a weaker spirit—that can advance to eminence in any line."},{"type":"paragraph","text":"The keynote that seems to be emerging from the passage is that"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"UPSC accepts A: the passage explicitly prescribes consulting wisely before resolving firmly. Its warning concerns indecision and changing plans without perseverance.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-003","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":3,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most crucial message conveyed by the above passage?","options":{"a":"Climate change has caused Arctic summer to be short but temperature to be high.","b":"Polar bears can be shifted to South Pole to ensure their survival.","c":"Without the presence of polar bears, the food chains in Arctic region will disappear.","d":"Climate change poses a threat to the survival of polar bears."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=3","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":3,"blocks":[{"type":"passage","text":"During the summer in the Arctic Ocean, sea ice has been melting earlier and faster, and the winter freeze has been coming later. In the last three decades, the extent of summer ice has declined by about 30 per cent. The lengthening period of summer melt threatens to undermine the whole Arctic food web, atop which stand polar bears."},{"type":"paragraph","text":"Which among the following is the most crucial message conveyed by the above passage?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Earlier melting and a shorter ice season threaten the Arctic food web on which polar bears depend. The immediate message is a threat to their survival.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-004","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":4,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which among the following is the most crucial message conveyed by the above passage?","options":{"a":"The ideas of purity and pollution are so deep-rooted that they cannot be removed from the minds of the people.","b":"People have to perceive toilet use and pit-emptying as clean and not polluting.","c":"People cannot change their old habits.","d":"People have neither civic sense nor sense of privacy."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=5","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":5,"blocks":[{"type":"passage","text":"Why do people prefer open defecation and not want toilets or, if they have them, only use them sometimes? Recent research has shown two critical elements: ideas of purity and pollution, and not wanting pits or septic tanks to fill because they have to be emptied. These are the issues that nobody wants to talk about, but if we want to eradicate the practice of open defecation, they have to be confronted and dealt properly."},{"type":"paragraph","text":"Which among the following is the most crucial message conveyed by the above passage?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The two barriers are beliefs about pollution and fear of emptying pits. Toilet use and pit-emptying must be regarded as clean if these barriers are to be overcome.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-005","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":5,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is the most crucial inference from the above passage?","options":{"a":"More emphasis should be laid on the development of natural capital.","b":"The growth driven by GDP only is neither desirable nor sustainable.","c":"The economic performance of the countries of the world is not satisfactory.","d":"The world needs more human capital under the present circumstances."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=5","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":5,"blocks":[{"type":"passage","text":"In the last two decades, the world’s gross domestic product (GDP) has increased by 50 per cent, whereas inclusive wealth has increased by a mere 6 per cent. In recent decades, GDP-driven economic performance has only harmed inclusive wealth like human capital; and natural capital like forests, land and water. While the world’s human capital which stands at 57 per cent of total inclusive wealth grew by only 8 per cent, the natural capital which is 23 per cent of total inclusive wealth declined by 30 per cent worldwide in the last two decades."},{"type":"paragraph","text":"Which of the following is the most crucial inference from the above passage?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"GDP rose much faster than inclusive wealth while natural capital declined. GDP growth alone can therefore conceal depletion of the resources that sustain well-being.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-006","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":6,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"Which of the following is most rational inference from the above passage?","options":{"a":"India must control its population growth so as to reduce its unemployment rate.","b":"Labour reforms are required in India to make optimum use of its vast labour force productively","c":"India is poised to achieve the double-digit growth very soon","d":"India is capable of supplying the skilled young people to other countries."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"By 2020, when the global economy is expected to run short of 56 million young people, India, with its youth surplus of 47 million, could fill the gap. It is in this context that labour reforms are often cited as the way to unlock double-digit growth in India. In 2014, India's labour force was estimated to be about 40 per cent of the population, but 93 per cent of this force was in unorganized sector. Over the last decade, the compound annual growth rate (CAGR) of employment has slowed to 0.5 per cent, with about 14 million jobs created during last year when the labour force increased by about 15 million."},{"type":"paragraph","text":"Which of the following is most rational inference from the above passage?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The demographic surplus is an opportunity, but slow job creation and widespread unorganized employment prevent its productive use. Labour reform is the supported inference.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-007","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":7,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The main idea of the passage is that","options":{"a":"it is essential for human beings to work","b":"there should be a balance between work and leisure","c":"working is a tyranny which we have to face","d":"human's understanding of the nature of work is essential"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"The very first lesson that should be taught to us when we are old enough to understand it, is that complete freedom from the obligation to work is unnatural, and ought to be illegal, as we can escape our share of the burden of work only by throwing it on someone else’s shoulders. Nature ordains that the human race shall perish of famine if it stops working. We cannot escape from this tyranny. The question we have to settle is how much leisure we can afford to allow ourselves."},{"type":"paragraph","text":"The main idea of the passage is that"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The passage says the human race would face famine without work and that escaping work shifts its burden onto others. Work is therefore essential.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-008","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":8,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The author suggests that habits","options":{"a":"tend to make our lives difficult","b":"add precision to our lives","c":"make it easier for us to live","d":"tend to mechanize our lives"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"There is no harm in cultivating habits so long as they are not injurious. Indeed, most of us are little more than bundle of habits. Take away our habits and the residuum would hardly be worth bothering about. We could not get on without them. They simplify the mechanism of life. They enable us to do a multitude of things automatically, which, if we had to give fresh and original thought to them each time, would make existence an impossible confusion."},{"type":"paragraph","text":"The author suggests that habits"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Useful habits make routine actions automatic and simplify life; thinking afresh about every action would create confusion.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-009","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":9,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"With reference to the above information, which one among the following statements must be true","options":{"a":"Some supporters of 'party Y' did not agree for the alliance with the \`party X'","b":"There is at least one supporter of \`party Y' who knew some supporters of 'party X' as a friend.","c":"No supporters of 'party X' supported Z's campaign strategy.","d":"No supporters of 'party X' knew Z."},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=7","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":7,"blocks":[{"type":"passage","text":"No supporters of 'party X', who knew Z and supported his campaign strategy, agreed for the alliance with 'party Y’; but some of them had friends in 'party Y'."},{"type":"paragraph","text":"With reference to the above information, which one among the following statements must be true"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Some supporters of X had friends in Y. Consequently at least one supporter of Y knew a supporter of X as a friend; the other options make unsupported claims.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-010","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":10,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"With reference to the above information, consider the following statement\\n1. Some supporters of 'party X' knew Z\\n2. Some supporters of 'party X', who opposed Z's campaign strategy, knew Z.\\n3. No supporters of 'party X' supported Z's campaign strategy. Which of the statements given above, is/are not correct?","options":{"a":"1 only","b":"2 and 3 only","c":"3 only","d":"1, 2 and 3"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":9,"blocks":[{"type":"passage","text":"No supporters of 'party X', who knew Z and supported his campaign strategy, agreed for the alliance with 'party Y’; but some of them had friends in 'party Y'."},{"type":"paragraph","text":"With reference to the above information, consider the following statement\\n1. Some supporters of 'party X' knew Z\\n2. Some supporters of 'party X', who opposed Z's campaign strategy, knew Z.\\n3. No supporters of 'party X' supported Z's campaign strategy. Which of the statements given above, is/are not correct?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The information establishes some X supporters who knew Z and supported his strategy. Statement 1 is supported; 3 contradicts it, while 2 adds an unsupported claim about opponents. UPSC accepts C, identifying statement 3 as not correct.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-011","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":11,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If second and fourth Saturdays and all the Sundays are taken as only holidays for an office, what would be the minimum number of possible working days of any month of any year?","options":{"a":"23","b":"22","c":"21","d":"20"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":9,"blocks":[{"type":"paragraph","text":"If second and fourth Saturdays and all the Sundays are taken as only holidays for an office, what would be the minimum number of possible working days of any month of any year?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"A 28-day February has four Sundays and two excluded Saturdays, leaving 28−6=22 working days. Longer months cannot have fewer under this holiday rule.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-012","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":12,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"If there is a policy that 1/3rd of population of a community has migrated every year from one place, to some other place, what is the leftover population of that community after the sixth year, if there is no further growth in the population during this period?","options":{"a":"16/243rd part of the population","b":"32/243rd part of the population","c":"32/729th part of the population","d":"64/729th part of the population"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":9,"blocks":[{"type":"paragraph","text":"If there is a policy that 1/3rd of population of a community has migrated every year from one place, to some other place, what is the leftover population of that community after the sixth year, if there is no further growth in the population during this period?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Two-thirds remain after each annual migration. After six years the fraction is (2/3)⁶=64/729.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-013","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":13,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Four tests—Physics, Chemistry, Mathematics and Biology are to be conducted on four consecutive days, not necessarily in the same order. The Physics test is held before the test which is conducted after Biology. Chemistry is conducted exactly after two tests are held. Which is the last test held?","options":{"a":"Physics","b":"Biology","c":"Mathematics","d":"Chemistry"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":9,"blocks":[{"type":"paragraph","text":"Four tests—Physics, Chemistry, Mathematics and Biology are to be conducted on four consecutive days, not necessarily in the same order. The Physics test is held before the test which is conducted after Biology. Chemistry is conducted exactly after two tests are held. Which is the last test held?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Chemistry is the third test. If Biology were second, the test after it would be Chemistry and Physics would have to be first; Mathematics is then fourth. Other valid placements also leave Mathematics last.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-014","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":14,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"The sum of income of A and B is more than that of C and D taken together. The sum of income of A and C is the same as that of B and D taken together. Moreover, A earns half as much as the sum of the income of B and D. Whose income is the highest?","options":{"a":"A","b":"B","c":"C","d":"D"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=9","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":9,"blocks":[{"type":"paragraph","text":"The sum of income of A and B is more than that of C and D taken together. The sum of income of A and C is the same as that of B and D taken together. Moreover, A earns half as much as the sum of the income of B and D. Whose income is the highest?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"A+C=B+D and A=(B+D)/2 imply C=A. Combining A+B>C+D gives B>D; since A is the mean of B and D, B also exceeds A and C.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-015","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":15,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following:\\nStatement: Good voice is a natural gift but one has to keep practising to improve and excel well in the field of music.\\nConclusions:\\nI. Natural gifts need nurturing and care.\\nII. Even though one’s voice is not good, one can keep practising.\\nWhich one of the following is correct in respect of the above statement and conclusions?","options":{"a":"Only conclusion I follows from the statement.","b":"Only conclusion II follows from the statement","c":"Either conclusion I or conclusion II follows from the statement","d":"Neither conclusion I nor conclusion II follows from the statement."},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"Consider the following:\\nStatement: Good voice is a natural gift but one has to keep practising to improve and excel well in the field of music.\\nConclusions:\\nI. Natural gifts need nurturing and care.\\nII. Even though one’s voice is not good, one can keep practising.\\nWhich one of the following is correct in respect of the above statement and conclusions?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The statement says a natural gift must be practised and developed, supporting conclusion I. It does not establish conclusion II about people without a good voice.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-016","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":16,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"There are three pillars X, Y and Z of different heights. Three spiders A, B and C start to climb on these pillars simultaneously. In one chance, A climbs on X by 6 cm but slips down 1 cm. B climbs on Y by 7 cm but slips down 3 cm. C climbs on Z by 6.5 cm but slips down 2 cm. If each of them requires 40 chances to reach the top of the pillars, what is the height of the shortest pillar?","options":{"a":"161 cm","b":"163 cm","c":"182 cm","d":"210 cm"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"There are three pillars X, Y and Z of different heights. Three spiders A, B and C start to climb on these pillars simultaneously. In one chance, A climbs on X by 6 cm but slips down 1 cm. B climbs on Y by 7 cm but slips down 3 cm. C climbs on Z by 6.5 cm but slips down 2 cm. If each of them requires 40 chances to reach the top of the pillars, what is the height of the shortest pillar?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The shortest pillar is Y: 39 complete climb-slip cycles give 39×4=156 cm, and the final climb adds 7 cm without slipping. Its height is 163 cm.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-017","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":17,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"“Rights are certain advantageous conditions of social well-being indispensable to the true development of the citizen.” In the light of this statement, which one of the following is the correct understanding of rights?","options":{"a":"Rights aim at individual good only.","b":"Rights aim at social good only.","c":"Rights aim at both individual and social good.","d":"Rights aim at individual good devoid of social well-being"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"“Rights are certain advantageous conditions of social well-being indispensable to the true development of the citizen.” In the light of this statement, which one of the following is the correct understanding of rights?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Rights are described as conditions of social well-being needed for the citizen’s development. Both individual development and social good are included.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-018","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":18,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"15 students failed in a class of 52. After removing the names of failed students, a merit order list has been prepared in which the position of Ramesh is 22nd from the top. What is his position from the bottom?","options":{"a":"18th","b":"17th","c":"16th","d":"15th"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"15 students failed in a class of 52. After removing the names of failed students, a merit order list has been prepared in which the position of Ramesh is 22nd from the top. What is his position from the bottom?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"There are 52−15=37 students in the merit list. Position from the bottom is 37−22+1=16.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-019","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":19,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the following: A+ B means A is the son of B. A - B means A is the wife of B. What does the expression P + R – Q mean?","options":{"a":"Q is the son of P","b":"Q is the wife of P.","c":"Q is the father of P.","d":"None of the above"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"Consider the following: A+ B means A is the son of B. A - B means A is the wife of B. What does the expression P + R – Q mean?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"P+R means P is R’s son. R−Q means R is Q’s wife. Q is therefore P’s father.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-020","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":20,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Gopal bought a cell phone and sold it to Ram at 10% profit. Then Ram wanted to sell it back to Gopal at 10% loss. What will be Gopal's position if he agreed?","options":{"a":"Neither loss nor gain","b":"Loss 1%","c":"Gain 1%","d":"Gain 0.5%"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=11","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":11,"blocks":[{"type":"paragraph","text":"Gopal bought a cell phone and sold it to Ram at 10% profit. Then Ram wanted to sell it back to Gopal at 10% loss. What will be Gopal's position if he agreed?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Use an original price of 100. Gopal receives 110 and buys back at 90% of 110=99. The phone returns to him with a gain of 1% relative to its original price.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-021","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":21,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The challenge the author of the above passage throws to the public is to achieve","options":{"a":"a high standard of living, progress and privileges","b":"equal privileges, fulfilment of destiny and political tolerance","c":"spirit of adventure and economic parity","d":"hard work, brotherhood and national unity"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":13,"blocks":[{"type":"passage","text":"We have hard work ahead. There is no resting for any of us till we redeem our pledge in full, till we make all the people of India what destiny intends them to be. We are citizens of a great country, on the verge of bold advance, and we have to live up to that high standard. All of us, to whatever religion we may belong, are equally the children of India with equal rights, privileges and obligations. We cannot encourage communalism or narrow mindedness, for no nation can be great whose people are narrow in thought or action."},{"type":"paragraph","text":"The challenge the author of the above passage throws to the public is to achieve"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The author calls for sustained work, equal membership of the nation, rejection of communalism and broad-minded action. These support hard work, brotherhood and national unity.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-022","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":22,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"In the light of the above passage, the nature of General Will is best described as","options":{"a":"the sum total of the private wills of the individuals","b":"what is articulated by the elected representatives of the individuals","c":"the collective good as distinct from private wills of the individuals","d":"the material interests of the community"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":13,"blocks":[{"type":"passage","text":"\\"The individual, according to Rousseau, puts his person and all his power in common under the supreme direction of the General Will and in our corporate capacity we receive each member as an indivisible part of the whole.\\""},{"type":"paragraph","text":"In the light of the above passage, the nature of General Will is best described as"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The General Will directs a collective whole in which individuals place their powers in common. It is the common good, rather than a mere sum of private wishes.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-023","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":23,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"What does the above passage imply?","options":{"a":"In a democracy, force is the main phenomenon in the actual exercise of sovereignty","b":"In a mature democracy, force to a great extent is the main phenomenon in the actual exercise of sovereignty.","c":"In a mature democracy, use of force is irrelevant in the actual exercise of sovereignty","d":"In a mature democracy, force is narrowed down to a marginal phenomenon in the actual exercise of sovereignty."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=13","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":13,"blocks":[{"type":"passage","text":"In a democratic State, where a high degree of political maturity of the people obtains, the conflict between the will of the sovereign law-making body and the organized will of the people seldom occurs."},{"type":"paragraph","text":"What does the above passage imply?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Political maturity makes conflict between the people and law-making authority rare. Force consequently has a marginal role; the passage does not say it disappears completely.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-024","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":24,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"This passage relates to","options":{"a":"duty to vote","b":"right to vote","c":"freedom to vote","d":"right to participate in politics"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"A successful democracy depends upon widespread interest and participation in politics, in which voting is an essential part. To deliberately refrain from taking such an interest, and from voting, is a kind of implied anarchy, it is to refuse one's political responsibility while enjoying the benefits of a free political society."},{"type":"paragraph","text":"This passage relates to"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The author treats abstention from politics and voting as refusal of political responsibility. The focus is the duty to vote.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-025","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":25,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"The passage seems to suggest that","options":{"a":"a leader foresees his future position","b":"a leader is chosen only by a free country","c":"a leader must see that his country is free from despair","d":"despair in a country sometimes leads to dictatorship"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"In a free country, the man who reaches the position of leader is usually one of outstanding character and ability. Moreover, it is usually possible to foresee that he will reach such a position, since early in life one can see his qualities of character. But this is not always true in the case of a dictator; often he reaches his position of power through chance, very often through the unhappy state of his country."},{"type":"paragraph","text":"The passage seems to suggest that"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"A dictator may obtain power through the unhappy condition of a country rather than an established record of character and ability. Despair can therefore facilitate dictatorship.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-026","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":26,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made :\\n1. People always see the leisure time as a gift and use it for acquiring more material possessions.\\n2. Use of leisure by some people to produce new and original things has been the chief source of human progress. Which of these assumptions is/are valid?","options":{"a":"1 ONLY","b":"2 ONLY","c":"BOTH 1 AND 2","d":"NEITHER 1 NOR 2"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=15","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":15,"blocks":[{"type":"passage","text":"The greatest blessing that technological progress has in store for mankind is not, of course, an accumulation of material possessions. The amount of these that can be effectively enjoyed by one individual in one lifetime is not great. But there is not the same narrow limit to the possibilities of the enjoyment of leisure. The gift of leisure may be abused by people who have had no experience of making use of it. Yet the creative use of leisure by a minority in societies has been the mainspring of all human progress beyond the primitive level."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made :\\n1. People always see the leisure time as a gift and use it for acquiring more material possessions.\\n2. Use of leisure by some people to produce new and original things has been the chief source of human progress. Which of these assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The passage explicitly credits creative use of leisure by a minority as the mainspring of progress. It also says leisure can be abused, so assumption 1 is unwarranted.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-027","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":27,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Reading comprehension","question":"With reference to the above passage, the following assumptions have been made:\\n1. A study of the famous battles of history would help us understand the modern warfare.\\n2. Studying the history is essential for anyone who aspires to be a leader. Which of these assumptions is/are valid?","options":{"a":"1 ONLY","b":"2 ONLY","c":"BOTH 1 AND 2","d":"NEITHER 1 NOR 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":17,"blocks":[{"type":"passage","text":"There is more than a modicum of truth in the assertion that \\"a working knowledge of ancient history is necessary to the intelligent interpretation of current events\\". But the sage who uttered these words of wisdom might well have added something on the benefits of studying particularly the famous battles of history for the lessons they contain for those of us who lead or aspire to leadership. Such a study will reveal certain qualities and attributes which enabled the winners to win—and certain deficiencies which caused the losers to lose. And the student will see that the same pattern recurs consistently, again and again, throughout the centuries."},{"type":"paragraph","text":"With reference to the above passage, the following assumptions have been made:\\n1. A study of the famous battles of history would help us understand the modern warfare.\\n2. Studying the history is essential for anyone who aspires to be a leader. Which of these assumptions is/are valid?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The passage offers lessons in leadership from historical battles, but does not assert either that these explain modern warfare or that all aspiring leaders must study history. Neither assumption necessarily follows.","concept":"Reading comprehension","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-028","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":28,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Suppose the average weight of 9 persons is 50 kg. The average weight of the first 5 persons is 45 kg, whereas the average weight of the last 5 persons is 55 kg. Then the weight of the 5th person will be","options":{"a":"45 kg","b":"47.5 kg","c":"50 kg","d":"52.5 Kg"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":17,"blocks":[{"type":"paragraph","text":"Suppose the average weight of 9 persons is 50 kg. The average weight of the first 5 persons is 45 kg, whereas the average weight of the last 5 persons is 55 kg. Then the weight of the 5th person will be"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The totals for the first and last five are 225 and 275 kg. Together they count the fifth person twice; subtract the nine-person total of 450 kg to obtain 50 kg.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-029","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":29,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a group of six women, there are four tennis players, four postgraduates in Sociology, one postgraduate in Commerce and three bank employees. Vimala and Kamla are the bank employees while Amala and Komala are unemployed. Komala and Nirmala are among the tennis players. Amala, Kamla, Komala and Nirmala are postgraduates in Sociology of whom two are bank employees. If Shyamala is a postgraduate in Commerce, who among the following is both a tennis player and a bank employee?","options":{"a":"Amala","b":"Komala","c":"Nirmala","d":"Shyamala"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":17,"blocks":[{"type":"paragraph","text":"In a group of six women, there are four tennis players, four postgraduates in Sociology, one postgraduate in Commerce and three bank employees. Vimala and Kamla are the bank employees while Amala and Komala are unemployed. Komala and Nirmala are among the tennis players. Amala, Kamla, Komala and Nirmala are postgraduates in Sociology of whom two are bank employees. If Shyamala is a postgraduate in Commerce, who among the following is both a tennis player and a bank employee?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Among the four Sociology postgraduates, two work in banks. Kamla is one; Amala and Komala are unemployed, so Nirmala must be the other. Nirmala is also a tennis player.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-030","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":30,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"P = (40% of A) + (65% of B) and Q = (50% of A) + (50% of B), where A is greater than B. In this context, which of the following statements is correct?","options":{"a":"P is greater than Q.","b":"Q is greater than P.","c":"P is equal to Q.","d":"None of the above can be concluded with certainty."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=17","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":17,"blocks":[{"type":"paragraph","text":"P = (40% of A) + (65% of B) and Q = (50% of A) + (50% of B), where A is greater than B. In this context, which of the following statements is correct?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"P−Q=−0.10A+0.15B. Knowing only A>B does not determine its sign: it depends on whether A/B is below, equal to or above 1.5.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-031","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":31,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A watch loses 2 minutes in every 24 hours while another watch gains 2 minutes in every 24 hours. At a particular instant, the two watches showed an identical time. Which of the following statements is correct if 24-hour clock is followed?","options":{"a":"The two watches show the identical time again on completion of 30 days.","b":"The two watches show the identical time again on completion of 90 days.","c":"The two watches show the identical time again on completion of 120 days.","d":"None of the above statements is correct."},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"A watch loses 2 minutes in every 24 hours while another watch gains 2 minutes in every 24 hours. At a particular instant, the two watches showed an identical time. Which of the following statements is correct if 24-hour clock is followed?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Their displayed times separate by 4 minutes per day. A 24-hour clock realigns after a separation of 1440 minutes, taking 360 days; none of the listed periods is correct.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-032","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":32,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a city, 12% of households earn less than Rs. 30,000 per year, 6% households earn more than Rs. 2,00,000 per year, 22% households earn more than Rs. 1,00,000 per year and 990 households earn between Rs. 30,000 and Rs. 1,00,000 per year. How many households earn between Rs. 1,00,000 and Rs. 2,00,000 per year?","options":{"a":"250","b":"240","c":"230","d":"225"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"In a city, 12% of households earn less than Rs. 30,000 per year, 6% households earn more than Rs. 2,00,000 per year, 22% households earn more than Rs. 1,00,000 per year and 990 households earn between Rs. 30,000 and Rs. 1,00,000 per year. How many households earn between Rs. 1,00,000 and Rs. 2,00,000 per year?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The middle-income group is 100−12−22=66% and contains 990 households, giving 1500 total households. The required group is 22−6=16%, or 240 households.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-033","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":33,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A clock strikes once at 1 o'clock, twice at 2 o'clock and thrice at 3 o'clock, and so on. If it takes 12 seconds to strike at 5 o'clock, what is the time taken by it to strike at 10 o'clock?","options":{"a":"20 seconds","b":"24 seconds","c":"28 seconds","d":"30 seconds"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"A clock strikes once at 1 o'clock, twice at 2 o'clock and thrice at 3 o'clock, and so on. If it takes 12 seconds to strike at 5 o'clock, what is the time taken by it to strike at 10 o'clock?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"UPSC’s final key accepts B, 24 seconds, using proportional stroke counts: 12×10/5. Under a fixed-gap interpretation there would be four gaps at 5 o’clock and nine at 10 o’clock, giving 27 seconds, which is absent from the options. The final key is retained for scoring.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-034","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":34,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Consider the given statement and the two conclusions that follow: Statement: Morning walk is good for health. Conclusions:\\n1. All healthy people go for morning walk.\\n2. Morning walk is essential for maintaining good health. What is/are the valid conclusion/ conclusions?","options":{"a":"1 ONLY","b":"2 ONLY","c":"BOTH 1 AND 2","d":"NEITHER 1 NOR 2"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=19","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":19,"blocks":[{"type":"paragraph","text":"Consider the given statement and the two conclusions that follow: Statement: Morning walk is good for health. Conclusions:\\n1. All healthy people go for morning walk.\\n2. Morning walk is essential for maintaining good health. What is/are the valid conclusion/ conclusions?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"“Good for health” does not imply that every healthy person walks or that walking is essential to health. Neither conclusion follows.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-035","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":35,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"There are thirteen 2-digit consecutive odd numbers. If 39 is the mean of the first five such numbers, then what is the mean of all the thirteen numbers?","options":{"a":"47","b":"49","c":"51","d":"45"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"There are thirteen 2-digit consecutive odd numbers. If 39 is the mean of the first five such numbers, then what is the mean of all the thirteen numbers?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The middle of the first five odd numbers is 39, so the first is 35. The middle of thirteen terms is the seventh, 35+6×2=47.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-036","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":36,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"Six boys A, B, C, D, E and F play a game of cards. Each has a pack of 10 cards. F borrows 2 cards from A and gives away 5 to C who in turn gives 3 to B while B gives 6 to D who passes 1 to E. Then the number of cards possessed by D and E is equal to the number of cards possessed by","options":{"a":"A, B and C","b":"B, C and F","c":"A, B and F","d":"A, C and F"},"answer":"b","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"Six boys A, B, C, D, E and F play a game of cards. Each has a pack of 10 cards. F borrows 2 cards from A and gives away 5 to C who in turn gives 3 to B while B gives 6 to D who passes 1 to E. Then the number of cards possessed by D and E is equal to the number of cards possessed by"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"After the transfers A=8, B=7, C=12, D=15, E=11, F=7. D+E=26, which equals B+C+F.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-037","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":37,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"There is a milk sample with 50% water in it. If 1/3rd of this milk is added to equal amount of pure milk, then water in the new mixture will fall down to","options":{"a":"25%","b":"30%","c":"35%","d":"40%"},"answer":"a","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"There is a milk sample with 50% water in it. If 1/3rd of this milk is added to equal amount of pure milk, then water in the new mixture will fall down to"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The diluted sample contributes half water and is mixed with an equal amount of pure milk. Its water fraction is halved from 50% to 25%.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-038","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":38,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"There are 4 horizontal and 4 vertical lines, parallel and equidistant to one another on a board. What is the maximum number of rectangles and squares that can be formed?","options":{"a":"16","b":"24","c":"36","d":"42"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"There are 4 horizontal and 4 vertical lines, parallel and equidistant to one another on a board. What is the maximum number of rectangles and squares that can be formed?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"A rectangle is determined by choosing two of the four horizontal lines and two of the four vertical lines: C(4,2)²=36. Squares are included in this count.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-039","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":39,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"A freight train left Delhi for Mumbai at an average speed of 40 km/hr. Two hours later, an express train left Delhi for Mumbai, following the freight train on a parallel track at an average speed of 60 km/hr. How far from Delhi would the express train meet the freight train?","options":{"a":"480 km","b":"260 km","c":"240 km","d":"120 km"},"answer":"c","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"A freight train left Delhi for Mumbai at an average speed of 40 km/hr. Two hours later, an express train left Delhi for Mumbai, following the freight train on a parallel track at an average speed of 60 km/hr. How far from Delhi would the express train meet the freight train?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"The freight train has an 80 km lead. The express gains 20 km each hour, catching it in 4 hours and travelling 60×4=240 km.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}},{"id":"upsc-2017-prelims-csat-a-040","year":2017,"stage":"CSAT","paper":"CSAT Paper II","number":40,"booklet":"A","questionType":"MCQ","subject":"CSAT","topic":"Quantitative aptitude & reasoning","question":"In a test, Randhir obtained more marks than the total marks obtained by Kunal and Debu. The total marks obtained by Kunal and Shankar are more than those of Randhir. Sonal obtained more marks than Shankar. Neha obtained more marks than Randhir. Who amongst them obtained highest marks?","options":{"a":"Randhir","b":"Neha","c":"Sonal","d":"Data are inadequate"},"answer":"d","keyStatus":"official","marks":2.5,"negativeMarks":0.8333333333333334,"wordLimit":0,"sourceUrl":"https://forumias.com/blog/wp-content/uploads/2021/01/CSAT-2017.pdf#page=21","keyUrl":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1","page":21,"blocks":[{"type":"paragraph","text":"In a test, Randhir obtained more marks than the total marks obtained by Kunal and Debu. The total marks obtained by Kunal and Shankar are more than those of Randhir. Sonal obtained more marks than Shankar. Neha obtained more marks than Randhir. Who amongst them obtained highest marks?"}],"sourceTitle":"UPSC CSE 2017 CSAT Paper II · Series A","explanation":{"justification":"Neha exceeds Randhir and Sonal exceeds Shankar, but their relative marks are not specified. Either Neha or Sonal could be highest.","concept":"Quantitative aptitude & reasoning","references":[{"title":"UPSC CSE 2017 final answer key · Series A","url":"https://lotusarise.com/wp-content/uploads/2021/12/UPSC-Prelims-Official-Answer-Key-2017-CSAT.pdf#page=1"}]}}]`);export{e as p};
